17→export function AgentPanel({ tables, onUpload, onLoadSample }: AgentPanelProps) {
18→  const { t } = useTranslation();
19→  const { messages, clearMessages } = useAgent();
20→  const bottomRef = useRef<HTMLDivElement>(null);
21→  const scrollContainerRef = useRef<HTMLDivElement>(null);
22→  const userScrolledUp = useRef(false);
23→
24→  const isNearBottom = useCallback(() => {
