28→  }, []);
29→
30→  const handleScroll = useCallback(() => {
31→    userScrolledUp.current = !isNearBottom();
32→  }, [isNearBottom]);
33→
34→  useEffect(() => {
35→    if (!userScrolledUp.current) {
36→      bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
